import anthropic

MAX_INPUT_TOKENS = 20000

client = anthropic.Anthropic()


class PromptTooExpensive(RuntimeError):
    pass


def assert_within(system, messages, model):
    """Refuse before dispatch. A count that does not refuse is not a ceiling."""
    counted = client.messages.count_tokens(
        model=model, system=system, messages=messages
    )
    if counted.input_tokens > MAX_INPUT_TOKENS:
        raise PromptTooExpensive(counted.input_tokens)
    return counted.input_tokens
